FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 200: frames and sweeps locked to cones and tori. Generated by tools/fixtures/gen-batch-200.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Each edge of a body: its length, and a B-spline's degree, knots and poles (indexed, as std does).
function wireProbe(context is Context, wires is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(wires, EntityType.EDGE)))
    {
        var entry = { "length" : roundToPrecision(evLength(context, { "entities" : edge }) / millimeter, 6) };
        try
        {
            const c = evCurveDefinition(context, { "edge" : edge });
            if (c is BSplineCurve)
            {
                var points = [];
                for (var i = 0; i < size(c.controlPoints); i += 1)
                    points = append(points, round6(c.controlPoints[i]));
                var knots = [];
                for (var i = 0; i < size(c.knots); i += 1)
                    knots = append(knots, roundToPrecision(c.knots[i], 9));
                entry.bspline = { "degree" : c.degree, "rational" : c.isRational, "points" : points, "knots" : knots };
            }
            else if (c is Circle)
                entry.circle = { "radius" : roundToPrecision(c.radius / millimeter, 6) };
            else if (c is Line)
                entry.line = true;
        }
        catch (error)
        {
            entry.curve = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// Each edge's ends.
function edgeEnds(context is Context, body is Query) returns array
{
    var out = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(body, EntityType.EDGE)))
    {
        const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 1], "arcLengthParameterization" : false });
        out = append(out, mapArray(lines, function(l) { return round6(l.origin); }));
    }
    return out;
}

// A frame profile, the only sketch of its own context, as a profile from an element library would be.
const squareTube = function(configuration is map) returns Context
{
    const context = newContextWithDefaults();
    const s = newSketchOnPlane(context, makeId("profile"), { "sketchPlane" : plane(vector(0, 0, 0) * meter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s, "outer", { "firstCorner" : vector(-2, -2) * millimeter, "secondCorner" : vector(2, 2) * millimeter });
    skRectangle(s, "inner", { "firstCorner" : vector(-1.5, -1.5) * millimeter, "secondCorner" : vector(1.5, 1.5) * millimeter });
    skSolve(s);
    return context;
};

function profileOf(build is function) returns PartStudioData
{
    return { "buildFunction" : build, "configuration" : {}, "partQuery" : qEverything(EntityType.BODY) } as PartStudioData;
}

// frame: a 4 mm square tube along a quarter circle on a cone frustum's side, its profile locked to the cone
export function c001(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(s, "line2", { "start" : vector(10, 0) * millimeter, "end" : vector(5, 20) * millimeter });
    skLineSegment(s, "line3", { "start" : vector(5, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(s, "line4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s);
    const axis = newSketchOnPlane(context, id + "axis", { "sketchPlane" : plane(vector(0, 0, -50) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(100, 0) * millimeter });
    skSolve(axis);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s"), "axis" : qCreatedBy(id + "axis", EntityType.EDGE), "fullRevolve" : true });
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 10) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(path, "a1", { "start" : vector(7.5, 0) * millimeter, "mid" : vector(5.303301, 5.303301) * millimeter, "end" : vector(0, 7.5) * millimeter });
    skSolve(path);
    frame(context, id + "frame1", { "profileSketch" : profileOf(squareTube), "selections" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "lockProfile" : true, "profileLockFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.CONE) });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID)) };
}

