// frame: the square tube along a quarter circle 45° up a cylinder's rounded top edge, locked to the round
export function c004(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(baseSketch, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    fillet(context, id + "fillet1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(10, 0, 10) * millimeter), "radius" : 3 * millimeter });
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 9.12132) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(path, "a1", { "start" : vector(9.12132, 0) * millimeter, "mid" : vector(6.449747, 6.449747) * millimeter, "end" : vector(0, 9.12132) * millimeter });
    skSolve(path);
    frame(context, id + "frame1", { "profileSketch" : profileOf(squareTube), "selections" : qOwnedByBody(qBodyType(qCreatedBy(id + "path", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "lockProfile" : true, "profileLockFaces" : qGeometry(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), GeometryType.TORUS) });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "frame1", EntityType.BODY), BodyType.SOLID)) };
}

